import{_ as e,o as t,c as r,a2 as l}from"./chunks/framework.F7eQ-ohH.js";const c=JSON.parse('{"title":"年龄问题","description":"","frontmatter":{},"headers":[],"relativePath":"行测/数量分析/11.年龄问题.md","filePath":"行测/数量分析/11.年龄问题.md","lastUpdated":1788883925000}'),o={name:"行测/数量分析/11.年龄问题.md"};function p(i,a,n,s,_,d){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="年龄问题" tabindex="-1">年龄问题 <a class="header-anchor" href="#年龄问题" aria-label="Permalink to &quot;年龄问题&quot;">​</a></h1><p>年龄问题是行测数量关系中高频且难度中等的题型，核心围绕 “时间推移下的年龄关系” 展开，其解题逻辑的根基的是两个关键特点，尤其第一个特点是所有题型的 “万能钥匙”。</p><h2 id="年龄差恒定不变" tabindex="-1">年龄差恒定不变 <a class="header-anchor" href="#年龄差恒定不变" aria-label="Permalink to &quot;年龄差恒定不变&quot;">​</a></h2><p>这是年龄问题的本质规律：<strong>无论时间向前推移（过去）还是向后推移（未来），两人之间的年龄差始终保持不变</strong>。例如，今年甲比乙大 5 岁，那么 5 年前、10 年后，甲依然比乙大 5 岁 —— 时间只会让两人的年龄同步增长或减少，不会改变年龄差的数值。这一特点是建立等量关系、列方程解题的核心依据。</p><h2 id="年龄的和差-差倍-关系" tabindex="-1">年龄的和差/ 差倍” 关系 <a class="header-anchor" href="#年龄的和差-差倍-关系" aria-label="Permalink to &quot;年龄的和差/ 差倍” 关系&quot;">​</a></h2><p>年龄问题很少单独考查单一关系，大多是 “年龄和”“年龄差”“年龄倍数” 的综合考查，需要结合 “和差问题”“差倍问题” 的解题思维，灵活转化题干条件，快速建立数量关系。基于 “年龄差恒定” 和 “和差关系”，衍生出两个核心公式，直接对应 “已知年龄和与年龄差，求各自年龄” 的基础题型：</p><ul><li>较大者的年龄 =（两人年龄和 + 两人年龄差）÷ 2</li><li>较小者的年龄 =（两人年龄和 - 两人年龄差）÷ 2</li></ul><p>上述公式适用场景是当题目明确给出 “两人现在的年龄和” 与 “年龄差” 时，可直接代入公式求解，无需复杂计算。</p><h1 id="真题" tabindex="-1">真题 <a class="header-anchor" href="#真题" aria-label="Permalink to &quot;真题&quot;">​</a></h1><p><strong>例题：甲对乙说当自己岁数是乙现在岁数时，乙才 4 岁；乙对甲说当自己岁数到甲现在岁数时，甲将有 67 岁，求甲乙现在各多少岁，给出了四个选项 ：</strong></p><p>A．45 岁，26 岁</p><p>B．46 岁，25 岁</p><p>C．47 岁，24 岁</p><p>D．48 岁，23 岁。</p><p>答案：B</p><p>解析：设甲的年龄为 X，乙的年龄为 Y，根据两人对话所体现的年龄关系列出方程组：</p><ul><li>第一个方程 Y - 4 = X - Y，它体现的是年龄差始终不变，从乙 4 岁到现在乙的年龄 Y，和从现在甲的年龄 X 到乙到甲现在年龄时这个过程中，年龄差是相等的。</li><li>第二个方程 67 - X = X - Y，其含义是从现在到乙达到甲现在年龄，再到甲之后达到 67 岁，这期间的年龄差也是不变的，和前面所描述的年龄差是同一个数值。</li></ul><p>通过解方程组得出 X = 46，Y = 25，所以答案选择 B 选项。</p>',18)])])}const u=e(o,[["render",p]]);export{c as __pageData,u as default};
